//! macOS concealed/password-manager pasteboard detection.
//!
//! 1Password, Bitwarden, and other managers mark items with a pasteboard type
//! instead of using a private pasteboard in every case. `ConcealedType` is the
//! standardized marker (nspasteboard.org); the rest are documented producer
//! markers.

use copyfie_platform::system::ConcealedProbe;

const MARKERS: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
    "application/x-nspasteboard-concealed-type",
];

pub struct MacConcealed;

impl ConcealedProbe for MacConcealed {
    fn is_concealed(&self, formats: &[String]) -> bool {
        formats.iter().any(|format| {
            MARKERS
                .iter()
                .any(|marker| format.eq_ignore_ascii_case(marker))
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_concealed_and_transient_markers() {
        let probe = MacConcealed;
        assert!(probe.is_concealed(&["org.nspasteboard.ConcealedType".to_string()]));
        assert!(probe.is_concealed(&[
            "public.utf8-plain-text".to_string(),
            "org.nspasteboard.TransientType".to_string()
        ]));
        assert!(probe.is_concealed(&["com.agilebits.onepassword".to_string()]));
    }

    #[test]
    fn plain_text_is_not_concealed() {
        let probe = MacConcealed;
        assert!(!probe.is_concealed(&[
            "public.utf8-plain-text".to_string(),
            "NSPasteboardTypeString".to_string()
        ]));
        assert!(!probe.is_concealed(&[]));
    }
}
